package route

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"sync"
	"sync/atomic"
	"time"
)

const currentDecisionPolicy = "route-policy-v1"
const maxDecisionRecords = 4096

// Private append-only evidence. It never restores permission or rules on restart.
type DecisionRecord struct {
	ID            string               `json:"id"`
	ConnectionID  string               `json:"connection_id"`
	Host          string               `json:"hostname"`
	TargetIP      string               `json:"target_ip"`
	Started       time.Time            `json:"started_at"`
	Completed     time.Time            `json:"completed_at"`
	Expires       time.Time            `json:"expires_at"`
	Policy        string               `json:"policy_version"`
	Scope         string               `json:"scope"`
	Diagnostic    EvaluationDiagnostic `json:"evaluation"`
	Adopted       bool                 `json:"policy_adopted"`
	Status        string               `json:"status"`
	PublicationID string               `json:"publication_id,omitempty"`
}

type decisionPublisher struct {
	firstDueMS atomic.Int64
	mu         sync.RWMutex
	records    []DecisionRecord
	session    string
	next       time.Time
	interval   time.Duration
}

func randomDecisionID() (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", fmt.Errorf("decision identifier unavailable")
	}
	return hex.EncodeToString(b[:]), nil
}

func newDecisionPublisher(c Config) (*decisionPublisher, error) {
	seconds := c.PublishIntervalSeconds
	if seconds == 0 {
		seconds = 30
	} // Also applies to programmatic constructors.
	if seconds < 1 || seconds > 3600 {
		return nil, fmt.Errorf("publish_interval_seconds must be 1..3600")
	}
	session, err := randomDecisionID()
	return &decisionPublisher{session: session, interval: time.Duration(seconds) * time.Second}, err
}

func (o *LabObserver) decisionScope() string {
	if o.control == nil {
		return ""
	}
	// Expiry may renew; immutable generation fields must not change.
	lease := o.control.lease
	lease.Expires = time.Time{}
	body, _ := json.Marshal(struct {
		Config Config
		Lease  Ownership
		Rules  []CoreRule
		Policy string
	}{o.c, lease, o.baseline, currentDecisionPolicy})
	return digest(body)
}

// Never log this private file or upload it. A new process starts with no records.
// A bounded ledger is intentionally not a database or a cross-session cache.
func (o *LabObserver) appendDecision(record DecisionRecord) error {
	if o.statePath == "" {
		return nil
	} // Unit tests without a lifecycle journal.
	path := o.statePath + ".decisions.jsonl"
	if info, err := os.Lstat(path); err == nil {
		if !info.Mode().IsRegular() || info.Size() >= 16<<20 {
			return fmt.Errorf("decision ledger limit or type invalid")
		}
	} else if !os.IsNotExist(err) {
		return fmt.Errorf("decision ledger unavailable")
	}
	body, err := json.Marshal(struct {
		Version int            `json:"version"`
		Session string         `json:"session"`
		Record  DecisionRecord `json:"record"`
	}{1, o.publisher.session, record})
	if err != nil {
		return fmt.Errorf("decision encoding failed")
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	if err != nil {
		return fmt.Errorf("decision ledger unavailable")
	}
	body = append(body, '\n')
	n, writeErr := f.Write(body)
	if writeErr == nil && n != len(body) {
		writeErr = fmt.Errorf("short decision write")
	}
	if writeErr == nil {
		writeErr = f.Sync()
	}
	closeErr := f.Close()
	if writeErr != nil || closeErr != nil {
		return fmt.Errorf("decision ledger write failed")
	}
	return nil
}

func (o *LabObserver) recordDecision(ctx context.Context, d Domain, r EvaluationDiagnostic, connectionID, targetIP, scope string, started time.Time) error {
	p := o.publisher
	p.mu.Lock()
	defer p.mu.Unlock()
	if len(p.records) >= maxDecisionRecords {
		return fmt.Errorf("decision record capacity reached")
	}
	id, err := randomDecisionID()
	if err != nil {
		return err
	}
	ttl := time.Duration(o.c.LearnedTTLSeconds) * time.Second
	if ttl > time.Minute {
		ttl = time.Minute
	}
	rec := DecisionRecord{ID: id, ConnectionID: connectionID, Host: d.Host, TargetIP: targetIP,
		Started: started, Completed: time.Now(), Expires: started.Add(ttl), Policy: currentDecisionPolicy,
		Scope: scope, Diagnostic: r, Status: "rejected"}
	rec.Adopted = ctx.Err() == nil && r.StageError == "none" && r.PolicyReason == "accepted" && (r.Decision == Direct || r.Decision == Proxy)
	if rec.Adopted && time.Now().Before(rec.Expires) {
		rec.Status = "pending"
		// A second suggestion cannot extend an existing result without new publication.
		for _, old := range p.records {
			if old.Host == rec.Host && (old.Status == "pending" || old.Status == "applied") && time.Now().Before(old.Expires) && old.Scope == rec.Scope {
				rec.Status = "superseded"
				break
			}
		}
	}
	if err := o.appendDecision(rec); err != nil {
		return err
	}
	p.records = append(p.records, rec)
	return nil
}

func (o *LabObserver) decisionReceipts() []map[string]any {
	if o.publisher == nil {
		return nil
	}
	p := o.publisher
	p.mu.RLock()
	defer p.mu.RUnlock()
	out := make([]map[string]any, 0, len(p.records))
	for _, r := range p.records {
		out = append(out, map[string]any{"id": r.ID, "connection_id": r.ConnectionID,
			"choice": r.Diagnostic.Choice, "decision": r.Diagnostic.Decision,
			"policy_reason": r.Diagnostic.PolicyReason, "policy_adopted": r.Adopted,
			"status": r.Status, "expires_at": r.Expires, "policy_version": r.Policy,
			"scope": r.Scope, "publication_id": r.PublicationID})
	}
	return out
}

func (o *LabObserver) endDecisions(status string, expiredOnly bool) error {
	if o.publisher == nil {
		return nil
	}
	p := o.publisher
	p.mu.Lock()
	defer p.mu.Unlock()
	for i, r := range p.records {
		if (r.Status != "pending" && r.Status != "applied") || (expiredOnly && time.Now().Before(r.Expires)) {
			continue
		}
		r.Status = status
		if err := o.appendDecision(r); err != nil {
			return err
		}
		p.records[i] = r
	}
	return nil
}

// Called by the serial worker on its own tick context, never the judgment job.
// Initialization occurs only after empty bootstrap and current ownership checks.
func (o *LabObserver) publishDue(ctx context.Context) error {
	p := o.publisher
	if p == nil || p.next.IsZero() || time.Now().Before(p.next) {
		return nil
	}
	now := time.Now()
	p.next = p.next.Add((now.Sub(p.next)/p.interval + 1) * p.interval)
	if err := o.control.check(); err != nil {
		return err
	}
	if err := o.unchanged(ctx); err != nil {
		return err
	}
	if err := o.control.checkPaths(ctx); err != nil {
		return err
	}
	if o.control.paused || o.control.maintenance.due(time.Now()) {
		return nil
	}
	scope := o.decisionScope()
	next := map[string]Entry{}
	p.mu.Lock()
	defer p.mu.Unlock()
	for i, r := range p.records {
		if r.Status != "pending" && r.Status != "applied" {
			continue
		}
		status := r.Status
		if !time.Now().Before(r.Expires) {
			status = "expired"
		} else if !r.Adopted || r.Policy != currentDecisionPolicy || r.Scope != scope {
			status = "invalidated"
		}
		if status != r.Status {
			r.Status = status
			if err := o.appendDecision(r); err != nil {
				return err
			}
			p.records[i] = r
			continue
		}
		next[r.Host] = Entry{Decision: r.Diagnostic.Decision, Expires: r.Expires}
	}
	o.Providers.mu.RLock()
	same := len(o.Providers.entries) == len(next) && !o.Providers.dirty
	for host, entry := range next {
		old, ok := o.Providers.entries[host]
		if !ok || old.Decision != entry.Decision || !old.Expires.Equal(entry.Expires) {
			same = false
		}
	}
	o.Providers.mu.RUnlock()
	if same {
		return o.Providers.Check(ctx) // Readback only: detect drift without re-submission.
	}
	if err := o.saveJournal("reconciling"); err != nil {
		return err
	}
	if err := o.Providers.Replace(ctx, next); err != nil {
		for i, r := range p.records {
			if r.Status == "pending" {
				r.Status = "failed"
				if persistErr := o.appendDecision(r); persistErr != nil {
					return persistErr
				}
				p.records[i] = r
			}
		}
		return err
	}
	if err := o.unchanged(ctx); err != nil {
		return err
	}
	if err := o.control.check(); err != nil {
		return err
	}
	// A slow ACK/readback must not promote a result after its validity ended.
	// Returning fails the worker closed; its existing owned drain clears cache.
	for _, entry := range next {
		if !time.Now().Before(entry.Expires) {
			return fmt.Errorf("publication result expired during ACK/readback")
		}
	}
	if err := o.saveJournal("active"); err != nil {
		return err
	}
	generation, _, _ := o.Providers.Status()
	publicationID := fmt.Sprintf("%s-%d", p.session, generation)
	for i, r := range p.records {
		if r.Status == "pending" {
			r.Status, r.PublicationID = "applied", publicationID
			if err := o.appendDecision(r); err != nil {
				return err
			}
			p.records[i] = r
		}
	}
	o.commits.Add(1)
	return nil
}

func (o *LabObserver) publicationSchedule() map[string]any {
	if o.publisher == nil {
		return nil
	}
	return map[string]any{"interval_seconds": int(o.publisher.interval / time.Second),
		"first_due_unix_ms":                 o.publisher.firstDueMS.Load(),
		"first_nonempty_submission_unix_ms": o.Providers.firstNonemptyMS.Load(),
		"nonempty_submissions":              o.Providers.nonemptySubmissions.Load()}
}

package route

import (
	"context"
	"io"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"
)

func preparedScheduledFixture(t *testing.T) *LabObserver {
	t.Helper()
	o, _, _ := controlledFixture(t)
	o.Providers.mu.Lock()
	o.Providers.dirty = false // Run normally establishes this with empty bootstrap ACK.
	o.Providers.mu.Unlock()
	o.publisher.next = time.Now().Add(time.Hour)
	return o
}

func TestScheduledJudgmentCannotPublishBeforeTickAndUsesFreshContext(t *testing.T) {
	o := preparedScheduledFixture(t)
	ctx, cancel := context.WithCancel(context.Background())
	if err := o.poll(ctx); err != nil {
		t.Fatal(err)
	}
	cancel() // The completed judgment grants no ongoing permission.
	if o.commits.Load() != 0 || len(o.decisionReceipts()) != 1 || o.decisionReceipts()[0]["status"] != "pending" {
		t.Fatal("not recorded pending")
	}
	if err := o.publishDue(context.Background()); err != nil {
		t.Fatal(err)
	}
	if _, count, _ := o.Providers.Status(); count != 0 {
		t.Fatal("published before tick")
	}
	if o.EvaluationDiagnostic().Publication != "not_attempted" {
		t.Fatal("evaluation claimed publication")
	}
	o.publisher.next = time.Now().Add(-time.Millisecond)
	if err := o.publishDue(context.Background()); err != nil {
		t.Fatal(err)
	}
	receipts := o.decisionReceipts()
	if o.commits.Load() != 1 || receipts[0]["status"] != "applied" || receipts[0]["publication_id"] == "" {
		t.Fatal("missing applied receipt")
	}
	gen, _, _ := o.Providers.Status()
	o.publisher.next = time.Now().Add(-time.Millisecond)
	if err := o.publishDue(context.Background()); err != nil {
		t.Fatal(err)
	}
	after, _, _ := o.Providers.Status()
	if gen != after || o.commits.Load() != 1 {
		t.Fatal("unchanged payload republished")
	}
	if err := o.reconcile(context.Background()); err != nil {
		t.Fatal(err)
	}
	if o.decisionReceipts()[0]["status"] != "withdrawn" {
		t.Fatal("drain retained authority")
	}
}

func TestScheduledExpiryRejectionAndVersionChangesDoNotBecomeRules(t *testing.T) {
	for _, change := range []string{"expiry", "policy", "rules", "uncertain", "late"} {
		t.Run(change, func(t *testing.T) {
			o := preparedScheduledFixture(t)
			if change == "uncertain" {
				o.judge = Stub{Answer: validAnswer(Uncertain)}
			}
			if change == "late" {
				o.c.PreflightMS = 5
				o.judge = Stub{Answer: validAnswer(Proxy), Wait: func(ctx context.Context) error { <-ctx.Done(); return nil }}
			}
			err := o.poll(context.Background())
			if change != "late" && err != nil {
				t.Fatal(err)
			}
			if change == "late" && err == nil {
				t.Fatal("late result accepted")
			}
			switch change {
			case "expiry":
				o.publisher.records[0].Expires = time.Now().Add(-time.Second)
			case "policy":
				o.publisher.records[0].Policy = "obsolete-policy"
			case "rules":
				o.c.Rules = []Rule{{Type: "DOMAIN", Value: "example.com", Route: Direct, Source: "manual"}}
			}
			o.publisher.next = time.Now().Add(-time.Millisecond)
			if err := o.publishDue(context.Background()); err != nil {
				t.Fatal(err)
			}
			if o.commits.Load() != 0 {
				t.Fatal("invalid result committed")
			}
			if _, count, _ := o.Providers.Status(); count != 0 {
				t.Fatal("invalid rule remains")
			}
			if o.decisionReceipts()[0]["status"] == "applied" {
				t.Fatal("invalid result applied")
			}
		})
	}
}

func TestScheduledTickRechecksOwnerAndNeverRestoresLedger(t *testing.T) {
	for _, change := range []string{"profile", "core", "lease"} {
		t.Run(change, func(t *testing.T) {
			o, guard, puts := controlledFixture(t)
			if err := o.poll(context.Background()); err != nil {
				t.Fatal(err)
			}
			switch change {
			case "profile":
				if err := os.WriteFile(o.control.lease.ConfigPath, []byte("different profile"), 0600); err != nil {
					t.Fatal(err)
				}
			case "core":
				guard.restarted.Store(true)
			case "lease":
				o.control.lease.Expires = time.Now().Add(-time.Second)
			}
			o.publisher.next = time.Now().Add(-time.Millisecond)
			if err := o.publishDue(context.Background()); err == nil {
				t.Fatal("stale ownership accepted")
			}
			if puts.Load() != 0 || o.commits.Load() != 0 {
				t.Fatal("write under stale authority")
			}
		})
	}
	o := preparedScheduledFixture(t)
	if err := o.poll(context.Background()); err != nil {
		t.Fatal(err)
	}
	before := o.publisher.session
	fresh, err := newDecisionPublisher(o.c)
	if err != nil {
		t.Fatal(err)
	}
	if fresh.session == before || len(fresh.records) != 0 || !fresh.next.IsZero() {
		t.Fatal("restored pending authority")
	}
	raw, err := os.ReadFile(o.statePath + ".decisions.jsonl")
	if err != nil || !strings.Contains(string(raw), o.publisher.records[0].ID) {
		t.Fatal("missing durable correlation")
	}
	for _, receipt := range o.decisionReceipts() {
		if _, ok := receipt["hostname"]; ok {
			t.Fatal("private hostname exposed")
		}
		if _, ok := receipt["target_ip"]; ok {
			t.Fatal("private address exposed")
		}
	}
}

func TestScheduledFailedACKCannotBeApplied(t *testing.T) {
	o := preparedScheduledFixture(t)
	if err := o.poll(context.Background()); err != nil {
		t.Fatal(err)
	}
	base := o.Providers.client.Transport
	o.Providers.client.Transport = localModelTransport(func(r *http.Request) (*http.Response, error) {
		if r.Method == http.MethodPut {
			return &http.Response{StatusCode: 500, Body: io.NopCloser(strings.NewReader("")), Header: http.Header{}}, nil
		}
		return base.RoundTrip(r)
	})
	o.publisher.next = time.Now().Add(-time.Millisecond)
	if err := o.publishDue(context.Background()); err == nil {
		t.Fatal("failed ACK accepted")
	}
	if o.commits.Load() != 0 || o.decisionReceipts()[0]["status"] != "failed" {
		t.Fatal("failed publication marked applied")
	}
}

func TestScheduledExpiryDuringACKCannotBeApplied(t *testing.T) {
	o := preparedScheduledFixture(t)
	if err := o.poll(context.Background()); err != nil {
		t.Fatal(err)
	}
	expires := time.Now().Add(500 * time.Millisecond)
	lateACKObserved := false
	o.publisher.records[0].Expires = expires
	base := o.Providers.client.Transport
	o.Providers.client.Transport = localModelTransport(func(r *http.Request) (*http.Response, error) {
		res, err := base.RoundTrip(r)
		if err == nil && r.Method == http.MethodPut && strings.HasSuffix(r.URL.Path, "proxy") {
			// Both writes were valid when submitted; only the last ACK is late.
			lateACKObserved = time.Now().Before(expires)
			time.Sleep(time.Until(expires) + time.Millisecond)
		}
		return res, err
	})
	o.publisher.next = time.Now().Add(-time.Millisecond)
	if err := o.publishDue(context.Background()); err == nil {
		t.Fatal("expired ACK accepted")
	}
	if !lateACKObserved {
		t.Fatal("test did not reach the valid submission / expired ACK boundary")
	}
	if o.commits.Load() != 0 || o.decisionReceipts()[0]["status"] == "applied" {
		t.Fatal("expired ACK marked applied")
	}
	if err := o.reconcile(context.Background()); err != nil {
		t.Fatal(err)
	}
	if _, count, _ := o.Providers.Status(); count != 0 {
		t.Fatal("expired cache not drained")
	}
}

package route

import (
	"context"
	"errors"
	"net/netip"
	"time"
)

// EvaluationDiagnostic is a bounded, host-free summary, not a history of model
// responses. A valid choice is a suggestion; only Decision is the policy result.
type EvaluationDiagnostic struct {
	Version                int      `json:"version"`
	Stage                  string   `json:"stage"`
	StageError             string   `json:"stage_error"`
	PolicyReason           string   `json:"policy_reason"`
	Choice                 Decision `json:"choice"`
	Decision               Decision `json:"decision"`
	Evidence               Evidence `json:"evidence"`
	DNS                    string   `json:"dns"`
	DeadlineMS             int64    `json:"deadline_ms"`
	ElapsedMS              int64    `json:"elapsed_ms"`
	DNSMS                  int64    `json:"dns_ms"`
	PathMS                 int64    `json:"path_ms"`
	DirectTLSMS            int64    `json:"direct_tls_ms"`
	ProxyTLSMS             int64    `json:"proxy_tls_ms"`
	CollectionMS           int64    `json:"collection_ms"`
	ModelMS                int64    `json:"model_ms"`
	PublicationMS          int64    `json:"publication_ms"`
	JobDeadlineMS          int64    `json:"job_deadline_ms"`
	JobElapsedMS           int64    `json:"job_elapsed_ms"`
	ModelCalls             int      `json:"model_calls"`
	ModelHTTPStatus        int      `json:"model_http_status,omitempty"`
	TransportAttempts      uint64   `json:"transport_attempts"`
	TransportAttemptsKnown bool     `json:"transport_attempts_known"`
	Publication            string   `json:"publication"`
	ConnectionTargetMatch  bool     `json:"connection_target_match"`
}

type EvaluationResult struct {
	State      State
	Diagnostic EvaluationDiagnostic
	// Internal correlation only. Never add the target address to public output.
	target netip.Addr
}

func boundedMS(d time.Duration) int64 {
	ms := d.Milliseconds()
	if ms < 0 {
		return 0
	}
	if ms > 600000 {
		return 600000
	}
	return ms
}

func remainingMS(ctx context.Context) int64 {
	if end, ok := ctx.Deadline(); ok {
		return boundedMS(time.Until(end))
	}
	return 10000
}

func stageError(ctx context.Context, fallback string) string {
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return "deadline_exceeded"
	}
	if ctx.Err() != nil {
		return "canceled"
	}
	return fallback
}

// Per-call context capture avoids borrowing an earlier/concurrent response code.
type modelHTTPStatusKey struct{}

type transportCounter interface{ transportAttempts() (uint64, bool) }

func modelAttempts(j Judge) (uint64, bool) {
	if counter, ok := j.(transportCounter); ok {
		return counter.transportAttempts()
	}
	return 0, false
}

// EvaluateEvidenceDetailed retains the existing ten-second upper bound and all
// Accept gates. Collection/model errors and policy refusals are separate labels.
func EvaluateEvidenceDetailed(parent context.Context, host string, collector EvidenceCollector, judge Judge) (result EvaluationResult, resultErr error) {
	start := time.Now()
	ctx, cancel := context.WithTimeout(parent, 10*time.Second)
	defer cancel()
	r := &result.Diagnostic
	*r = EvaluationDiagnostic{Version: 1, Stage: "normalize", StageError: "none", PolicyReason: "not_evaluated", Choice: Uncertain, Decision: Uncertain, Evidence: Evidence{"not_tested", "not_tested"}, DNS: "not_tested", DeadlineMS: remainingMS(ctx), Publication: "not_attempted"}
	defer func() { r.ElapsedMS = boundedMS(time.Since(start)) }()
	d, err := Normalize(host)
	if err != nil {
		r.StageError = "input_invalid"
		return result, err
	}
	result.State = State{Hostname: d.Host, Registrable: d.Registrable, Evidence: r.Evidence}
	if collector == nil || judge == nil {
		r.StageError = "input_invalid"
		return result, errAcceptance
	}
	_, r.TransportAttemptsKnown = modelAttempts(judge)
	r.Stage = "collection"
	started := time.Now()
	probe, err := collector.Collect(ctx, d)
	r.CollectionMS = boundedMS(time.Since(started))
	r.DNSMS, r.PathMS, r.DirectTLSMS, r.ProxyTLSMS = probe.timing.DNSMS, probe.timing.PathMS, probe.timing.DirectTLSMS, probe.timing.ProxyTLSMS
	r.DNS, r.Evidence, result.State.Evidence, result.target = probe.DNS, probe.Evidence, probe.Evidence, probe.target
	if probe.stage != "" {
		r.Stage = probe.stage
	}
	if err != nil {
		r.StageError = stageError(ctx, "collection_failed")
		return result, err
	}
	if ctx.Err() != nil {
		r.StageError = stageError(ctx, "collection_failed")
		return result, ctx.Err()
	}
	if r.Evidence.DirectTLS != "verified_success" && !(r.Evidence.DirectTLS == "repeated_failure" && r.Evidence.ProxyTLS == "verified_success") {
		r.Stage, r.PolicyReason = "policy", "evidence_insufficient"
		return result, nil
	}
	r.Stage, r.ModelCalls = "model", 1
	before, known := modelAttempts(judge)
	started = time.Now()
	modelContext := context.WithValue(ctx, modelHTTPStatusKey{}, &r.ModelHTTPStatus)
	answer, err := judge.Decide(modelContext, result.State)
	r.ModelMS = boundedMS(time.Since(started))
	after, knownAfter := modelAttempts(judge)
	r.TransportAttemptsKnown = known && knownAfter && after >= before
	if r.TransportAttemptsKnown {
		r.TransportAttempts = after - before
	}
	if err != nil {
		r.StageError = stageError(ctx, acceptanceModelReason(err))
		return result, err
	}
	if answer.Choice.Valid() {
		r.Choice = answer.Choice
	}
	if ctx.Err() != nil {
		r.StageError = stageError(ctx, "model_unavailable")
		return result, ctx.Err()
	}
	r.Stage = "policy"
	r.Decision, r.PolicyReason = acceptWithReason(result.State, answer)
	return result, nil
}

package route

